package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/doctor") public class DoctorController{private final DoctorService s;public DoctorController(DoctorService s){this.s=s;}@PostMapping public ResponseEntity<DoctorDTO> create(@Valid @RequestBody DoctorDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<DoctorDTO> all(){return s.all();}@GetMapping("/{id}") public DoctorDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public DoctorDTO update(@PathVariable Long id,@Valid @RequestBody DoctorDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/department/{id}") public List<DoctorDTO> department(@PathVariable Long id){return s.department(id);}}
